24	// skillsCollectionRef returns the collection to offer, overridable via
25	// INTROPY_SKILLS_COLLECTION (useful for testing against a local registry).
26	func skillsCollectionRef() string {
27		return cmp.Or(os.Getenv("INTROPY_SKILLS_COLLECTION"), defaultSkillsCollectionRef)
28	}
