30	// decideInstallSkills is the pure gating logic for the post-scaffold skills
31	// install: --skip-install-skills forces a no and --install-skills forces a
32	// yes, both without prompting; otherwise --no-input and non-terminal stdin
33	// skip, and an interactive session gets a [Y/n] prompt (default yes).
34	func decideInstallSkills(force, skip, noInput bool, in io.Reader, errW io.Writer) (bool, error) {
35		if skip {
36			return false, nil
37		}
38		if force {
39			return true, nil
40		}
41		if noInput {
42			return false, nil
43		}
44		f, ok := in.(*os.File)
45		if !ok || !term.IsTerminal(int(f.Fd())) {
46			return false, nil
47		}
48		return confirmInstallSkills(in, errW)
49	}
50	
51	// maybeInstallSkills applies decideInstallSkills and, on yes, does the
52	// equivalent of `skills collection add` plus `skills add` for every skill in
53	// the collection. On no, it prints how to install later — unless the skip
54	// was the explicit --skip-install-skills, where a hint would just be noise.
55	func maybeInstallSkills(ctx context.Context, in io.Reader, errW io.Writer, force, skip, noInput bool, outputDir string) error {
56		install, err := decideInstallSkills(force, skip, noInput, in, errW)
57		if err != nil {
58			return err
59		}
60		ref := skillsCollectionRef()
61		if !install {
62			if !skip {
63				fmt.Fprintf(errW, "skills not installed — run 'intropy skills collection add --name %s --ref %s' in the integration later\n",
64					defaultSkillsCollectionAlias, ref)
65			}
66			return nil
67		}
68	
69		project, err := skillProjectAt(outputDir)
70		if err != nil {
71			return err
72		}
73		client, err := oci.NewClient()
74		if err != nil {
75			return err
76		}
77		installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
78		adder := skill.NewAdder(client, installer, project)
79	
80		entries, err := skill.NewCollectionInstaller(client, adder, project).
81			InstallAll(ctx, defaultSkillsCollectionAlias, ref)
82		if err != nil {
83			return err
84		}
85		for _, e := range entries {
86			fmt.Fprintf(errW, "  installed %s @ %s -> %s\n", e.Name, e.Source.Tag, e.Path)
87		}
88		fmt.Fprintf(errW, "installed %d skill(s) from %s\n", len(entries), ref)
89		return nil
