111	// skillProjectAt returns the skills project rooted exactly at dir, creating an
112	// empty skills.json there if the blueprint didn't ship one. Unlike
113	// resolveOrBootstrapProject it never walks up: the scaffolded integration is
114	// its own skills project even when created inside a larger repo.
115	func skillProjectAt(dir string) (*skill.Project, error) {
116		abs, err := filepath.Abs(dir)
117		if err != nil {
118			return nil, err
119		}
120		p := &skill.Project{Root: abs}
121		if _, err := os.Stat(p.ManifestPath()); err == nil {
122			return p, nil
123		} else if !os.IsNotExist(err) {
124			return nil, err
125		}
126		if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
127			return nil, fmt.Errorf("bootstrap skills.json: %w", err)
128		}
129		return p, nil
130	}
