package blueprint

// Throwaway harness: renders the local blueprint working copies to verify
// agent.md/README template changes. Run with:
//   go test ./internal/blueprint -run TestLocalRenderHarness -v
// Delete this file after use.

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLocalRenderHarness(t *testing.T) {
	if os.Getenv("LOCAL_RENDER") == "" {
		t.Skip("set LOCAL_RENDER=1 to run")
	}
	blueprintsRoot := "/Users/robinhultman/dev/intropy/blueprints"
	outRoot := os.Getenv("LOCAL_RENDER_OUT")
	if outRoot == "" {
		outRoot = t.TempDir()
	}
	cases := []struct {
		name string
		sets map[string]any
	}{
		{"hello-world", map[string]any{"name": "Int1055.OrderSync"}},
		{"transactional", map[string]any{"name": "Int1055.OrderSync", "empty": false}},
	}
	for _, tc := range cases {
		tpl, err := LoadTemplate(filepath.Join(blueprintsRoot, tc.name, "template.yaml"))
		if err != nil {
			t.Fatalf("%s: load: %v", tc.name, err)
		}
		values, err := Resolve(tpl, nil, nil, tc.sets, nil)
		if err != nil {
			t.Fatalf("%s: resolve: %v", tc.name, err)
		}
		dest := filepath.Join(outRoot, tc.name)
		if err := Render(filepath.Join(blueprintsRoot, tc.name, "skeleton"), dest, values); err != nil {
			t.Fatalf("%s: render: %v", tc.name, err)
		}
		t.Logf("%s rendered to %s", tc.name, dest)
	}
}

